/**
 * 偶然中文（m.or7.net）书源 jsLib
 * 约束：纯 ES5（Rhino 兼容）；jsLib 函数内不得直接引用 java / baseUrl / book，
 *       一律由规则行当参数传入（Legado 作用域限制）。
 */

/* ================= 通用工具 ================= */
function kbTrim(s) {
    return String(s === null || s === undefined ? '' : s).replace(/^[\s\u00a0\u3000]+|[\s\u00a0\u3000]+$/g, '');
}

function kbEsc(s) {
    return String(s === null || s === undefined ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function kbUnescape(s) {
    var t = String(s === null || s === undefined ? '' : s);
    t = t.replace(/&nbsp;/gi, ' ').replace(/&ensp;/gi, ' ').replace(/&emsp;/gi, '\u3000');
    t = t.replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"');
    t = t.replace(/&apos;/gi, "'").replace(/&#39;/g, "'").replace(/&amp;/gi, '&');
    t = t.replace(/&#x([0-9a-f]+);/gi, function (m, h) {
        return String.fromCharCode(parseInt(h, 16));
    });
    t = t.replace(/&#(\d+);/g, function (m, d) {
        return String.fromCharCode(parseInt(d, 10));
    });
    return t;
}

var KB_STATUS = {
    '连载中': '连载', '連載中': '连载', '连载': '连载', '已完結': '完结',
    '已完结': '完结', '完結': '完结', '完结': '完结', '全本': '完结'
};

function kbCleanChip(v) {
    var t = String(v === null || v === undefined ? '' : v);
    t = t.replace(/<[^>]+>/g, ' ');
    t = t.replace(/[\[\]【】\{\}（）\(\)<>《》「」『』〔〕〖〗]/g, ' ');
    t = t.replace(/^[\s#＃♯]+/g, '');
    t = t.replace(/[\s\u00a0\u3000]+/g, ' ');
    t = kbTrim(t);
    if (!/[0-9a-zA-Z\u4e00-\u9fa5]/.test(t)) return '';
    return t;
}

function kbChips(s) {
    var raw = String(s === null || s === undefined ? '' : s);
    var parts = raw.split(/[\s\u3000,，、#＃|｜/／]+/), out = [], seen = {}, i, t;
    for (i = 0; i < parts.length; i++) {
        t = kbCleanChip(parts[i]);
        if (!t) continue;
        if (seen[t]) continue;
        seen[t] = 1;
        out.push(t);
    }
    return out.join(',');
}

function kbStatus(v) {
    var t = kbCleanChip(v);
    if (!t) return '';
    if (KB_STATUS[t]) return KB_STATUS[t];
    if (/完结|完本|全本/.test(t)) return '完结';
    if (/连载|連載|未完/.test(t)) return '连载';
    return t;
}

/* 简介：切段 + 每段两个全角空格（简介区不会自动缩进） */
var KB_IND = '\u3000\u3000';

function kbIndentParas(text) {
    var t = String(text === null || text === undefined ? '' : text);
    t = t.replace(/<br\s*\/?>/gi, '\n');
    t = t.replace(/<\/(p|div|h[1-6]|li|tr)>/gi, '\n');
    t = t.replace(/<[^>]+>/g, '');
    t = kbUnescape(t);
    t = t.replace(/\r\n?/g, '\n');
    var lines = t.split('\n'), out = [], i, l, buf = [];
    for (i = 0; i < lines.length; i++) {
        l = kbTrim(lines[i]);
        if (!l || l.length < 2) continue;
        out.push(KB_IND + l);
    }
    if (!out.length) return '';
    buf = out.join('\n');
    return buf;
}

function kbDate(v) {
    if (v === null || v === undefined || v === '') return '';
    var s = String(v);
    var m = s.match(/(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})/);
    if (m) {
        return m[1] + '-' + (m[2].length < 2 ? '0' + m[2] : m[2]) + '-' + (m[3].length < 2 ? '0' + m[3] : m[3]);
    }
    return kbTrim(s);
}

/* ================= 偶然中文 站点函数 ================= */
var OR7_HOST = 'https://m.or7.net';

function or7Abs(u) {
    var s = String(u === null || u === undefined ? '' : u);
    if (/^https?:\/\//i.test(s)) return s;
    if (s.charAt(0) === '/') return OR7_HOST + s;
    if (s.length > 0) return OR7_HOST + '/' + s;
    return OR7_HOST;
}

/* 挑战页判定：很短、含「内容正在载入」与 var c2= */
function or7IsChallenge(h) {
    var s = String(h === null || h === undefined ? '' : h);
    if (!s) return false;
    if (s.length > 3000) return false;
    return s.indexOf('var c2=') > -1 && s.indexOf('nnxswnn') > -1 || (s.indexOf('var c2=') > -1 && s.indexOf('内容正在载入') > -1);
}

/* 从挑战脚本里截出 function ajax(xxyyu){ } 并求值为函数 */
function or7ExtractFn(code) {
    var s = String(code === null || code === undefined ? '' : code);
    var i = s.indexOf('function ajax(');
    if (i < 0) return null;
    var j = s.indexOf('{', i), depth = 0, k, ch;
    if (j < 0) return null;
    for (k = j; k < s.length; k++) {
        ch = s.charAt(k);
        if (ch === '{') depth++;
        else if (ch === '}') {
            depth--;
            if (depth === 0) break;
        }
    }
    if (depth !== 0) return null;
    var src = s.substring(i, k + 1);
    var fn = null;
    try { fn = eval('(' + src + ')'); } catch (e) { fn = null; }
    return fn;
}

/* 完成一次挑战：取 c2 → 拉脚本 → 算校验地址 → 请求一次（服务端据此种 cookie） */
function or7Pass(h, pageUrl, java) {
    var s = String(h === null || h === undefined ? '' : h);
    var mc = s.match(/var\s+c2\s*=\s*"([^"]+)"/);
    var mj = s.match(/src\s*=\s*"([^"]*\/nn[a-z0-9]*\/[0-9]+\.js[^"]*)"/i);
    if (!mc || !mj) return false;
    var c2 = mc[1];
    var jsUrl = or7Abs(mj[1]);
    var code = '';
    try { code = String(java.ajax(jsUrl) || ''); } catch (e) { code = ''; }
    if (code.length < 200) return false;
    var fn = or7ExtractFn(code);
    if (!fn) return false;
    var path = '';
    try { path = String(fn(c2) || ''); } catch (e2) { path = ''; }
    if (!path) return false;
    var ok = '';
    try { ok = String(java.ajax(or7Abs(path)) || ''); } catch (e3) { ok = ''; }
    return ok.replace(/\s/g, '').indexOf('ok') === 0;
}

/* 抓页面：命中挑战则自动过一次，再重取 */
function or7Fetch(url, java) {
    var u = or7Abs(url), h = '', attempt;
    for (attempt = 0; attempt < 3; attempt++) {
        h = '';
        try { h = String(java.ajax(u) || ''); } catch (e) { h = ''; }
        if (or7IsChallenge(h)) {
            if (or7Pass(h, u, java)) {
                try { h = String(java.ajax(u) || ''); } catch (e2) { h = ''; }
            }
        }
        if (h && h.length > 800 && !or7IsChallenge(h)) break;
    }
    return h;
}

/* 取 dl 块里的第一个匹配 */
function or7One(blk, re) {
    var m = String(blk === null || blk === undefined ? '' : blk).match(re);
    return m ? m[1] : '';
}

/* 列表页 / 分类页 / 排行页：把 dl.B（大卡）与 dl.S（横滑卡）统一成自建结构 */
function or7List(html) {
    var s = String(html === null || html === undefined ? '' : html);
    var out = [], re = /<dl class="(?:B|S)"[^>]*>([\s\S]*?)<\/dl>/g, m;
    while ((m = re.exec(s)) !== null) {
        var blk = m[1];
        var url = or7One(blk, /<dt[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"/i);
        var name = or7One(blk, /<dt[^>]*>[\s\S]*?<a[^>]*href="[^"]*"[^>]*>([\s\S]*?)<\/a>/i);
        if (!url || !name) continue;
        name = kbTrim(kbUnescape(name.replace(/<[^>]+>/g, '')));
        if (!name) continue;
        var cover = or7One(blk, /<img[^>]*\bdata-src="([^"]+)"/i);
        if (!cover) cover = or7One(blk, /<img[^>]*\bsrc="([^"]+)"/i);
        var author = or7One(blk, /作者[：:]\s*([^<]+?)\s*</i);
        var intro = or7One(blk, /简介[：:]\s*([\s\S]*?)<\/dd>/i);
        var last = or7One(blk, /最新章节[：:]\s*<a[^>]*>([\s\S]*?)<\/a>/i);
        var date = or7One(blk, /更新时间[：:]\s*(\d{4}-\d{2}-\d{2})/i);
        intro = kbTrim(kbUnescape(intro.replace(/<[^>]+>/g, '')));
        last = kbTrim(kbUnescape(last.replace(/<[^>]+>/g, '')));
        out.push('<dl class="kb-b"><dt><a class="kb-n" href="' + kbEsc(or7Abs(url)) + '">' + kbEsc(name) + '</a></dt>'
            + '<dd class="kb-c"><img class="kb-p" data-src="' + kbEsc(or7Abs(cover)) + '" alt=""></dd>'
            + '<dd class="kb-a">' + kbEsc(kbTrim(author)) + '</dd>'
            + '<dd class="kb-d">' + kbEsc(intro) + '</dd>'
            + '<dd class="kb-l"><a>' + kbEsc(last) + '</a></dd>'
            + '<dd class="kb-t">' + kbEsc(date) + '</dd></dl>');
    }
    return out.join('\n');
}

/* 搜索：站内搜索需图形验证码（无法程序化），改为「热门库本地匹配」
 * 数据源：书库 / 完本 / 排行 —— 约 210 本，覆盖站点主推书目 */
function or7KeyOf(baseUrl) {
    var s = String(baseUrl === null || baseUrl === undefined ? '' : baseUrl);
    var m = s.match(/[?&]kw=([^&]*)/);
    if (!m) return '';
    var v = m[1].replace(/\+/g, ' ');
    try { v = decodeURIComponent(v); } catch (e) { }
    return kbTrim(v);
}

function or7Search(html, baseUrl, java) {
    var kw = or7KeyOf(baseUrl);
    var pm = String(baseUrl).match(/[?&]p=(\d+)/);
    if (pm && parseInt(pm[1], 10) > 1) return '';      // 本地聚合只有一页
    var pages = [];
    pages.push(String(html === null || html === undefined ? '' : html));
    var extra = ['/', '/finish/', '/rank/', '/or7151/', '/or7152/', '/or7153/',
        '/or7154/', '/or7155/', '/or7156/', '/or7157/', '/or7158/', '/or7159/'];
    for (var i = 0; i < extra.length; i++) {
        var h = '';
        try { h = or7Fetch(extra[i], java); } catch (e) { h = ''; }
        if (h) pages.push(h);
    }
    var all = or7List(pages.join('\n'));
    var out = [], j, blk, nm, au, hit, words, seen = {};
    var reSplit = /<dl class="kb-b">[\s\S]*?<\/dl>/g;
    var m2;
    var list = [];
    while ((m2 = reSplit.exec(all)) !== null) list.push(m2[0]);
    if (!kw) return pages.length ? or7List(pages.join('\n')) : '';
    words = kw.split(/[\s\u3000]+/);
    for (j = 0; j < list.length; j++) {
        blk = list[j];
        nm = or7One(blk, /<a class="kb-n"[^>]*>([\s\S]*?)<\/a>/i);
        au = or7One(blk, /<dd class="kb-a">([\s\S]*?)<\/dd>/i);
        hit = true;
        for (var w = 0; w < words.length; w++) {
            if (!words[w]) continue;
            if (nm.indexOf(words[w]) < 0 && au.indexOf(words[w]) < 0) { hit = false; break; }
        }
        var hid = or7One(blk, /href="([^"]+)"/i);
        if (hit && hid && !seen[hid]) { seen[hid] = 1; out.push(blk); }
    }
    if (!out.length) {
        return '<dl class="kb-b"><dt><a class="kb-n" href="' + OR7_HOST + '">没找到《' + kbEsc(kw) + '》</a></dt>'
            + '<dd class="kb-a">偶然中文</dd>'
            + '<dd class="kb-d">站内搜索需要图形验证码，书源只能用「书库/完本/排行」热门书目做本地匹配（约 210 本）。冷门书请到发现页翻，或在浏览器里打开站点搜到书后复制书籍链接。</dd>'
            + '<dd class="kb-t"></dd></dl>';
    }
    return out.join('\n');
}

/* 详情页：从 og: 元信息取分类 + 状态 */
function or7Meta(html, prop) {
    var s = String(html === null || html === undefined ? '' : html);
    var re1 = new RegExp('<meta[^>]+property="' + prop + '"[^>]*content="([^"]*)"', 'i');
    var re2 = new RegExp('<meta[^>]+content="([^"]*)"[^>]*property="' + prop + '"', 'i');
    var m = s.match(re1) || s.match(re2);
    return m ? kbUnescape(m[1]) : '';
}

function or7Kind(html) {
    var cat = kbChips(or7Meta(html, 'og:novel:category'));
    var st = kbStatus(or7Meta(html, 'og:novel:status'));
    var out = [];
    if (cat) out.push(cat);
    if (st) out.push(st);
    return out.join(',');
}

function or7BookId(u) {
    var m = String(u === null || u === undefined ? '' : u).match(/\/or7\/(\d+)/);
    return m ? m[1] : '';
}

/* 目录：tocUrl 留空（Legado 复用详情页 HTML），这里自己抓 /or7/{id}/list.html */
function or7Toc(html, baseUrl, java) {
    var id = or7BookId(baseUrl);
    var h = '';
    if (id) {
        try { h = or7Fetch('/or7/' + id + '/list.html', java); } catch (e) { h = ''; }
    }
    if (!id) id = or7BookId(html);
    if ((!h || h.indexOf('MLlist') < 0) && id) {
        try { h = or7Fetch('/or7/' + id + '/list.html', java); } catch (e2) { h = ''; }
    }
    if (!h || h.indexOf('MLlist') < 0) {
        // 兜底：详情页里的最新章节
        var d = String(html === null || html === undefined ? '' : html);
        var nb = d.match(/<ul class="Newlist">([\s\S]*?)<\/ul>/);
        if (nb) h = '<ul class="MLlist">' + nb[1] + '</ul>';
    }
    var um = String(h).match(/<ul class="MLlist">([\s\S]*?)<\/ul>/);
    if (!um) return '<div class="kb-c"><a href="' + kbEsc(OR7_HOST) + '">△ 目录解析异常，请刷新重试</a></div>';
    var body = um[1];
    var out = [], re = /<li[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, m;
    while ((m = re.exec(body)) !== null) {
        var u = m[1], n = kbTrim(kbUnescape(m[2].replace(/<[^>]+>/g, '')));
        if (!u || !n) continue;
        if (u.indexOf('/or7b/') < 0) continue;
        out.push('<div class="kb-c"><a href="' + kbEsc(or7Abs(u)) + '">' + kbEsc(n) + '</a></div>');
    }
    if (!out.length) return '<div class="kb-c"><a href="' + kbEsc(OR7_HOST) + '">△ 目录为空，请刷新重试</a></div>';
    return out.join('\n');
}

/* 正文广告行判定（只对整行命中，避免误伤正文） */
function or7IsAd(l) {
    var t = String(l === null || l === undefined ? '' : l);
    if (!t) return true;
    if (/^本章.{0,8}(未完|没完)/.test(t)) return true;
    if (/请点击下.{0,2}页/.test(t)) return true;
    if (/^温馨提示/.test(t)) return true;
    if (/^请勿依赖搜索/.test(t)) return true;
    if (/^如果被.{0,6}转.{0,2}码/.test(t)) return true;
    if (/^正在手打|^努力更新中|^近期更新缓慢/.test(t)) return true;
    if (/崔更|催更/.test(t) && t.length < 60) return true;
    if (/^如果此章是作者求票/.test(t)) return true;
    if (/^请你先收藏|^如果你还没注册/.test(t)) return true;
    if (/偶然中文\]?\s*m\.or7\.net/.test(t)) return true;
    if (/提醒您[：:].*(收藏|订阅)/.test(t)) return true;
    if (/下次我更新您才方便继续阅读/.test(t)) return true;
    if (/看完记得收藏/.test(t)) return true;
    if (/^[.．·…。\s]+$/.test(t)) return true;
    if (/^\d{5,}。*$/.test(t)) return true;
    return false;
}

/* 正文：切成 <p>，去首行重复标题、去尾部催更/广告 */
function or7Novel(html) {
    var t = String(html === null || html === undefined ? '' : html);
    t = t.replace(/<script[\s\S]*?<\/script>/gi, '');
    t = t.replace(/<style[\s\S]*?<\/style>/gi, '');
    t = t.replace(/<br\s*\/?>/gi, '\n');
    t = t.replace(/<p[^>]*>/gi, '\n');      // 本站 <p> 不闭合，必须当分隔符
    t = t.replace(/<\/p>/gi, '\n');
    t = t.replace(/<\/div>/gi, '\n');
    t = t.replace(/<[^>]+>/g, '');
    t = kbUnescape(t);
    t = t.replace(/\r\n?/g, '\n');
    t = t.replace(/[\u200b\u200c\u200d\ufeff]/g, '');
    var lines = t.split('\n'), out = [], i, l, first = true;
    for (i = 0; i < lines.length; i++) {
        l = kbTrim(lines[i]);
        if (!l) continue;
        if (first) {
            first = false;
            if (/^第?\s*[0-9零一二三四五六七八九十百千两]{1,8}\s*[、\.．章节回]/.test(l) && l.length < 40) continue;
        }
        if (or7IsAd(l)) continue;
        l = l.replace(/[…\.]{1,4}\s*。。\s*$/, '').replace(/^[…\.]{2,}\s*。\s*$/, '');
        l = kbTrim(l);
        if (!l || l.length < 2) continue;
        out.push('<p>' + kbEsc(l) + '</p>');
    }
    if (!out.length) return '<p>△ 本章内容为空，请换源或刷新重试</p>';
    return out.join('\n');
}

/* 正文入口：命中挑战则过一次再重取 */
function or7Content(html, baseUrl, java) {
    var h = String(html === null || html === undefined ? '' : html);
    if (or7IsChallenge(h)) {
        var u = or7Abs(baseUrl);
        if (or7Pass(h, u, java)) {
            try { h = String(java.ajax(u) || ''); } catch (e) { h = ''; }
        } else {
            return '<p>△ 正文获取失败：站点反爬验证未通过，请刷新本章重试</p>';
        }
    }
    var m = h.match(/<div class="TxtContent"[^>]*>([\s\S]*?)<\/div>/);
    if (!m) {
